class T(unittest.TestCase):
    def test_case(self):
        class Proxy():
            def __getattr__(me, name): return 'fb:' + name
        p = Proxy()
        self.assertEqual(p.whatever, 'fb:whatever')

class T(unittest.TestCase):
    def test_case(self):
        def probe():
            class Boom():
                def __get__(me, obj, owner):
                    raise AttributeError('nope')
            class C():
                x = Boom()
                def __getattr__(me, name):
                    return 'tail:' + name
            return C().x
        self.assertEqual(probe(), 'tail:x')

class T(unittest.TestCase):
    def test_case(self):
        class It():
            def __init__(me, data): me.data = data
            def __iter__(me): return iter(me.data)
        self.assertEqual(sum(It([1, 2])), 3)

class T(unittest.TestCase):
    def test_case(self):
        class It():
            def __init__(me, data): me.data = data
            def __iter__(me): return iter(me.data)
        self.assertEqual(tuple(It([1, 2])), (1, 2))
        self.assertEqual(list(enumerate(It(['a']))), [(0, 'a')])
